function totalsByCustomer(orders) {
  const totals = new Map();
  for (const { customerId, total } of orders) {
    if (!Number.isFinite(total) || total < 0) throw new TypeError('Invalid total');
    totals.set(customerId, (totals.get(customerId) ?? 0) + total);
  }
  return totals;
}

